SELECT * FROM material_textbook_extracts
WHERE material_id = #{materialId} AND file_hash = #{fileHash}
  AND extractor_version = #{extractorVersion} AND user_id = #{userId}

SELECT e.* FROM material_textbook_extracts e
JOIN course_materials m ON m.material_id = e.material_id AND m.file_hash = e.file_hash
     AND m.status = 'ACTIVE' AND m.user_id = e.user_id
WHERE e.user_id = #{userId} AND e.extractor_version = #{extractorVersion}
  AND e.material_id IN
#{id}

