UPDATE material_textbook_extracts SET clue_json = #{clueJson}
 WHERE extract_id = #{extractId} AND user_id = #{userId}
   AND (clue_json IS NULL OR JSON_VALUE(clue_json, '$.source') = 'SIGNAL')
